// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 warpTime, address actor) public {
        vm.assume(actor != address(0));
        uint256 bn = bound(blockNum, 0, 1_000_000);
        uint256 wt = bound(warpTime, block.timestamp + 1, block.timestamp + 1_000_000);

        vm.roll(bn);
        vm.warp(wt);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        uint256 expected = (bn % 15 == 0) ? 0 : 20 ether;
        assertTrue(ok && address(c).balance == expected);
    }
}
